def solve(inp):
    H=len(inp); W=len(inp[0]); n=H//3
    bands=[[inp[b*3+i][j] for j in range(W)] for b in range(n)]
    # base band: one whose color is most frequent overall? all demos: band0 is 5-block. Use band with most common color count.
    doms=[]
    for b,bk in enumerate(bands):
